from z3 import *

def solve_graph():
    n = 15
    E = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    s = Solver()

    # Symmetry of edges
    for i in range(n):
        for j in range(n):
            if i == j:
                s.add(Not(E[i][j]))
            elif i < j:
                s.add(E[i][j] == E[j][i])

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    import itertools

    # length 3
    for c in itertools.combinations(range(n), 3):
        s.add(Not(And(E[c[0]][c[1]], E[c[1]][c[2]], E[c[2]][c[0]])))

    # length 4
    for c in itertools.permutations(range(n), 4):
        if c[0] < c[1] and c[0] < c[2] and c[0] < c[3] and c[1] < c[3]:
            s.add(Not(And(E[c[0]][c[1]], E[c[1]][c[2]], E[c[2]][c[3]], E[c[3]][c[0]])))

    # length 5
    for c in itertools.permutations(range(n), 5):
        if c[0] == min(c) and c[1] < c[4]:
            s.add(Not(And(E[c[0]][c[1]], E[c[1]][c[2]], E[c[2]][c[3]], E[c[3]][c[4]], E[c[4]][c[0]])))

    # length 6
    for c in itertools.permutations(range(n), 6):
        if c[0] == min(c) and c[1] < c[5]:
            s.add(Not(And(E[c[0]][c[1]], E[c[1]][c[2]], E[c[2]][c[3]], E[c[3]][c[4]], E[c[4]][c[5]], E[c[5]][c[0]])))

    # At least 22 edges
    edge_vars = [E[i][j] for i in range(n) for j in range(i+1, n)]
    s.add(Sum([If(e, 1, 0) for e in edge_vars]) >= 22)

    # 4-colorable
    C = [Int(f"c_{i}") for i in range(n)]
    for i in range(n):
        s.add(C[i] >= 0, C[i] < 4)
    for i in range(n):
        for j in range(i+1, n):
            s.add(Implies(E[i][j], C[i] != C[j]))

    if s.check() == sat:
        m = s.model()
        edges = [(i, j) for i in range(n) for j in range(i+1, n) if is_true(m[E[i][j]])]
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve_graph()

