import itertools

n = 15
edges = list(itertools.combinations(range(n), 2))
edge_idx = {e: i+1 for i, e in enumerate(edges)}

def get_idx(u, v):
    if u > v:
        u, v = v, u
    return edge_idx[(u, v)]

from pysat.solvers import Solver

with Solver(name='g4') as s:
    # No C3
    for c in itertools.combinations(range(n), 3):
        s.add_clause([-get_idx(c[0], c[1]), -get_idx(c[1], c[2]), -get_idx(c[0], c[2])])

    # No C4
    for c in itertools.combinations(range(n), 4):
        for p in itertools.permutations(c):
            if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
                s.add_clause([-get_idx(p[0], p[1]), -get_idx(p[1], p[2]), -get_idx(p[2], p[3]), -get_idx(p[3], p[0])])

    # No C5
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[4]:
                s.add_clause([-get_idx(p[0], p[1]), -get_idx(p[1], p[2]), -get_idx(p[2], p[3]), -get_idx(p[3], p[4]), -get_idx(p[4], p[0])])

    # No C6
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] == min(p) and p[1] < p[5]:
                s.add_clause([-get_idx(p[0], p[1]), -get_idx(p[1], p[2]), -get_idx(p[2], p[3]), -get_idx(p[3], p[4]), -get_idx(p[4], p[5]), -get_idx(p[5], p[0])])

    # At least 22 edges
    cnf = CardEnc.atleast(lits=[i+1 for i in range(len(edges))], bound=22, encoding=1)
    for clause in cnf.clauses:
        s.add_clause(clause)

    print("Solving...")
    if s.solve():
        print("SAT")
        model = s.get_model()
        res = [edges[i-1] for i in model if i > 0 and i <= len(edges)]
        print(res)
    else:
        print("UNSAT")

